@keyframes chakra-effect{0%,12%{opacity:0}26%,78%{opacity:1}100%{opacity:0}}
@keyframes chakra-sparks{0%,18%{opacity:0;transform:translateY(10px)}45%{opacity:.9}90%,100%{opacity:0;transform:translateY(-22px)}}
@keyframes chakra-arm{0%,10%,100%{transform:rotate(0)}30%,75%{transform:rotate(-17deg)}}
@keyframes chakra-body{0%,15%,100%{transform:translateY(0)}30%,76%{transform:translateY(-4px)}}
@keyframes orb-charge{0%,13%{transform:scale(.1)}35%{transform:scale(.8) rotate(30deg)}65%{transform:scale(1) rotate(180deg)}80%{transform:scale(1.3) rotate(300deg)}100%{transform:scale(.3) rotate(380deg)}}
@keyframes chakra-projectile{0%,60%{opacity:0;transform:scaleX(.1)}73%{opacity:.9;transform:scaleX(1)}88%,100%{opacity:0;transform:scaleX(1.1)}}
@keyframes clone-left{0%,15%{opacity:0;transform:translateX(95px)}33%,74%{opacity:.6;transform:translateX(0)}100%{opacity:0;transform:translateX(-8px)}}
@keyframes clone-right{0%,20%{opacity:0;transform:translateX(-95px)}38%,76%{opacity:.6;transform:translateX(0)}100%{opacity:0;transform:translateX(8px)}}
@keyframes electric-flash{0%,100%{opacity:1}50%{opacity:.25}}
@keyframes flame-project{0%,18%{transform:scale(.05);opacity:0}44%,70%{transform:scale(1);opacity:1}90%,100%{transform:translateX(20px) scale(1.1);opacity:0}}
@keyframes black-flame{0%,20%{transform:scaleY(.05)}48%{transform:scaleY(1.1) skewX(-4deg)}65%{transform:scaleY(.95) skewX(4deg)}82%{transform:scaleY(1.1) skewX(-3deg)}100%{transform:scaleY(.2)}}
@keyframes eye-illusion{0%,15%{transform:scale(.3);opacity:0}45%{transform:scale(1);opacity:1}80%{transform:scale(1.08);opacity:.8}100%{transform:scale(1.2);opacity:0}}
@keyframes armor-rise{0%,17%{transform:scaleY(.1)}42%,78%{transform:scaleY(1)}100%{transform:scaleY(.85)}}
@keyframes vortex-turn{0%,15%{transform:scale(.1) rotate(0)}50%{transform:scale(1) rotate(90deg)}80%{transform:scale(.8) rotate(240deg)}100%{transform:scale(.1) rotate(340deg)}}
@keyframes shinobi-teleport{0%,25%,100%{transform:translateX(0);opacity:1}28%,34%{opacity:0}35%,65%{transform:translateX(150px);opacity:1}68%,75%{opacity:0}76%,99%{transform:translateX(0);opacity:1}}
@keyframes summon-smoke{0%,35%{transform:scale(.1);opacity:0}55%{transform:scale(1);opacity:.8}90%,100%{transform:scale(1.4) translateY(-20px);opacity:0}}
@keyframes healing-pulse{0%,100%{transform:scale(.7);opacity:.5}50%{transform:scale(1.05);opacity:1}}
@keyframes shinobi-strike{0%,20%,100%{transform:translateX(0)}35%{transform:translateX(35px) rotate(-4deg)}50%{transform:translateX(18px) rotate(3deg)}70%{transform:translateX(47px) rotate(-2deg)}85%{transform:translateX(8px)}}
@keyframes shadow-stretch{0%,15%{transform:scaleX(.05)}45%,80%{transform:scaleX(1)}100%{transform:scaleX(.05)}}
@keyframes demo-progress{from{width:0}to{width:100%}}
