  const worldPeople = id => new Set(data.villageLinks.filter(r=>r.group===id&&byId.has(r.person)).map(r=>r.person));
  function worldGroups(type,allowed){
    const teams=type==='teams', groups=teams?data.teams:data.clans,links=teams?data.teamLinks:data.clanLinks,buckets=new Map();
    groups.forEach(g=>{const key=fold(g.name).trim();if(!buckets.has(key))buckets.set(key,{id:g.id,name:g.name,groupIds:new Set(),members:new Set()});buckets.get(key).groupIds.add(g.id)});
    const index=new Map();buckets.forEach(g=>g.groupIds.forEach(id=>index.set(id,g)));
    links.forEach(r=>{if(allowed.has(r.person))index.get(teams?r.team:r.group)?.members.add(r.person)});
    return [...buckets.values()].filter(g=>g.members.size).sort((a,b)=>b.members.size-a.members.size||a.name.localeCompare(b.name));
  }
