tics','Leitura tática'],['matrix','Mapa de respostas'],['arsenal','Arsenal cruzado'],['links','Linhagens & laços']].map(([key,label])=>`<button id="duel-tab-${key}" role="tab" aria-selected="${state.duelTab===key}" aria-controls="duel-tab-panel" tabindex="${state.duelTab===key?0:-1}" data-duel-tab="${key}">${label}</button>`).join('')}</div><button class="duel-common-badge" data-duel-action="shared"><strong class="common-number">${fmt(common.length)}</strong><span>técnicas em comum</span>${icon('arrow',14)}</button></div><div id="duel-tab-panel" class="duel-tab-panel" role="tabpanel" aria-labelledby="duel-tab-${state.duelTab}"></div></section></section>`;
