    const line=(i,incoming)=>{const p=point(i),dx=p.x-210,dy=p.y-154,len=Math.hypot(dx,dy),sx=210+dx/len*58,sy=154+dy/len*58,tx=p.x-dx/len*27,ty=p.y-dy/len*27;return incoming?`M${tx},${ty} Q${210-dy*.27},${154+dx*.27} ${sx},${sy}`:`M${sx},${sy} Q${210-dy*.27},${154+dx*.27} ${tx},${ty}`};
    $('#duel-wheel').innerHTML=`<svg class="duel-wheel-svg" viewBox="0 0 420 310" role="group" aria-label="Relações de ${focus.name}: supera ${strong.name}; cede a ${weak.name}"><defs><marker id="duel-arrow-good" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="none" stroke="#8bceb0" stroke-width="1.5"/></marker><marker id="duel-arrow-risk" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="none" stroke="#d78787" stroke-width="1.5"/></marker></defs><circle cx="210" cy="154" r="124" class="duel-orbit"/><circle cx="210" cy="154" r="95" class="duel-orbit inner"/>${duelElements.map((_,i)=>{const p=point(i);return `<path d="M210 154 ${p.x} ${p.y}" class="duel-wheel-ray"/>`}).join('')}<path class="duel-flow good" d="${line((index+1)%5,false)}" marker-end="url(#duel-arrow-good)"/><path class="duel-flow risk" d="${line((index+4)%5,true)}" marker-end="url(#duel-arrow-risk)"/><circle cx="210" cy="154" r="57" class="duel-focus-circle" style="--element:${focus.color}"/><text x="210" y="148" class="duel-focus-jp" fill="${focus.color}">${focus.jp}</text><text x="210" y="177" class="duel-focus-name" fill="${focus.color}">${focus.name}</text><text x="210" y="192" class="duel-focus-caption">${state.duelFocusSide?'NATUREZA DE '+state.duelFocusSide.toUpperCase():'CONSULTA LIVRE'}</text>${duelElements.map((e,i)=>{const p=point(i);return `<g class="duel-element-node ${e.key===focus.key?'focused':''}" data-duel-focus="${e.key}" tabindex="0" role="button" aria-label="Ver relações de ${e.name}" aria-pressed="${e.key===focus.key}" style="--element:${e.color}" transform="translate(${p.x} ${p.y})"><title>${e.name}: supera ${duelElements[(i+1)%5].name}, cede a ${duelElements[(i+4)%5].name}</title><circle class="duel-node-aura" r="28"/><circle r="21"/><svg x="-12" y="-12" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="${e.color}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${e.path}"/></svg><text y="39" class="duel-node-name">${e.name}</text>${state.duelA===e.key?'<rect x="-30" y="-27" width="15" height="14" rx="4" class="duel-node-marker a"/><text x="-22.5" y="-17" class="duel-node-marker-label">A</text>':''}${state.duelB===e.key?'<rect x="15" y="-27" width="15" height="14" rx="4" class="duel-node-marker b"/><text x="22.5" y="-17" class="duel-node-marker-label">B</text>':''}</g>`}).join('')}</svg>`;
    $('#duel-element-legend').innerHTML=`<span class="good">Supera <b>${strong.name}</b></span><i></i><span class="risk">Cede a <b>${weak.name}</b></span>`;
    root.querySelectorAll('.duel-wheel-switch button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.side===state.duelFocusSide)));
  }
  function renderDuelVerdict(){
