      panel.innerHTML=`<div class="duel-matrix-layout"><div class="duel-matrix-copy"><span class="eyebrow">A ATACA / B RESPONDE</span><h3>O próximo lance<br><em>muda a leitura.</em></h3><p>As células ativas cruzam as naturezas registradas para os dois ninjas. Selecione um par para mudar o lance acima.</p><div class="duel-matrix-legend"><span class="advantage">↑ A supera B</span><span class="disadvantage">↓ B supera A</span><span>＝ Mesma natureza</span><span>· Sem relação direta</span></div><small>A roda descreve naturezas, não imunidades do personagem. A vantagem pressupõe técnicas de nível comparável.</small></div><div class="duel-matrix-table"><table aria-label="Matriz de vantagens elementais A contra B"><thead><tr><th>A ↓ / B →</th>${duelElements.map(e=>`<th scope="col" style="--element:${e.color}">${duelGlyph(e.key,18)}<span>${e.name}</span></th>`).join('')}</tr></thead><tbody>${duelElements.map(e=>`<tr><th scope="row" style="--element:${e.color}">${duelGlyph(e.key,18)}<span>${e.name}</span></th>${duelElements.map(f=>{const relation=duelRelation(e.key,f.key),label=relation==='advantage'?'A supera B':relation==='disadvantage'?'B supera A':relation==='same'?'Mesma natureza':'Sem relação direta',enabled=availableA.has(e.key)&&availableB.has(f.key);return `<td><button class="duel-matrix-cell ${relation} ${state.duelA===e.key&&state.duelB===f.key?'selected':''}" data-duel-pair-a="${e.key}" data-duel-pair-b="${f.key}" aria-label="${e.name} contra ${f.name}: ${label}${!enabled?'; sem registro para um dos ninjas':''}" title="${e.name} × ${f.name}: ${label}" ${enabled?'':'disabled'}>${relation==='advantage'?'↑':relation==='disadvantage'?'↓':relation==='same'?'＝':'·'}</button></td>`}).join('')}</tr>`).join('')}</tbody></table><small>Apagado: natureza sem registro para um dos ninjas.</small></div></div>`;
    }else if(state.duelTab==='arsenal'){
      const ta=techniquesFor(a.id),tb=techniquesFor(b.id),shared=[...ta].filter(id=>tb.has(id)),onlyA=[...ta].filter(id=>!tb.has(id)),onlyB=[...tb].filter(id=>!ta.has(id));
      panel.innerHTML=`<div class="duel-arsenal-tools"><div class="duel-arsenal-filters" role="group" aria-label="Recorte do arsenal">${[['shared','Em comum',shared.length],['a','Só no catálogo de A',onlyA.length],['b','Só no catálogo de B',onlyB.length]].map(([key,label,count])=>`<button data-duel-action="arsenal-filter" data-filter="${key}" aria-pressed="${state.duelArsenal===key}">${label} <b>${fmt(count)}</b></button>`).join('')}</div>${search('Buscar no arsenal cruzado...',state.duelQuery,'duel-tech-search')}</div><div id="duel-tech-results"></div><p class="duel-catalog-limit">“Só no catálogo” indica a associação nesta base; não prova exclusividade da técnica no universo Naruto.</p>`;
