    }else{
      const sharedTeams=actualTeams(a.id).filter(n=>actualTeams(b.id).includes(n)),sharedInherited=inheritedFor(a.id).filter(n=>inheritedFor(b.id).includes(n));
      const linksCard=(c,side)=>`<article class="duel-links-card duel-side-${side}"><div class="duel-tactic-title"><span>${side.toUpperCase()} / ${esc(c.name)}</span>${villageSymbol(c)}</div><h4>Linhagens & habilidades</h4><div class="duel-link-chips">${inheritedFor(c.id).map(n=>`<span>${esc(n)}</span>`).join('')||'<small>Sem registros de linhagem ou habilidade especial.</small>'}</div><h4>Equipes registradas</h4><div class="duel-link-chips">${actualTeams(c.id).map(n=>`<span>${esc(n)}</span>`).join('')||'<small>Sem equipes registradas.</small>'}</div><h4>Naturezas fora do ciclo básico</h4><div class="chakra-list">${(natureByPerson.get(c.id)||[]).filter(n=>!duelElements.some(e=>n.replace(/\s*\(.*$/,'').trim()===e.release)).map(n=>`<span class="chip">${esc(nameForChakra(n))}</span>`).join('')||'<small>Sem naturezas adicionais registradas.</small>'}</div></article>`;
      panel.innerHTML=`<div class="duel-context-note">CONEXÕES EM COMUM · ${sharedTeams.length} equipes e ${sharedInherited.length} linhagens ou habilidades. Naturezas combinadas, Yin e Yang permanecem fora da tabela de superioridade básica.</div><div class="duel-tactics-grid">${linksCard(a,'a')}${linksCard(b,'b')}</div>`;
    }
  }
  function renderDuelTechList(){
