  function showDuelPicker(side){state.duelPickerSlot=side;state.duelPickerQuery='';showModal('Escolha o shinobi '+side.toUpperCase(),`${search('Nome, clã ou vila...',state.duelPickerQuery,'duel-pick-search')}<div id="duel-picker-results"></div>`);$('.modal').classList.add('duel-picker-modal');renderDuelPicker();$('#duel-pick-search').focus()}
  function renderDuelPicker(){const rows=data.characters.filter(c=>fold([c.name,c.clan,c.village].join(' ')).includes(fold(state.duelPickerQuery))).sort((a,b)=>(a.rank||99999)-(b.rank||99999)||a.name.localeCompare(b.name));$('#duel-picker-results').innerHTML=`<p class="duel-tech-caption">${Math.min(60,rows.length)} de ${fmt(rows.length)} resultados · refine a busca pelo nome, clã ou vila.</p><div class="duel-picker-grid">${rows.slice(0,60).map(c=>`<button data-duel-action="choose" data-id="${c.id}">${picture(c,'',true)}<span><strong>${esc(c.name)}</strong><small>${esc(c.village||'Origem não informada')}</small></span></button>`).join('')||'<div class="empty">Nenhum shinobi encontrado.</div>'}</div>`}
  function showDuelRules(){
    showModal('Como ler um confronto shinobi.',`<div class="duel-rule-cycle">${duelElements.map(e=>`<span style="--element:${e.color}">${duelGlyph(e.key)}${e.name}<b>→</b></span>`).join('')}<span>Fogo</span></div><h3>Vantagem de natureza</h3><p>O ciclo compara técnicas elementais de nível comparável: uma natureza supera a seguinte e cede à anterior. A relação não é uma imunidade do corpo do ninja e não define o vencedor do combate. Escala, chakra, execução e situação alteram a leitura.</p><p>${sourceLink(duelEditorial.cycleSource,'Ciclo publicado no NARUTO Official ↗')} · O artigo descreve também regras próprias de um jogo de evento; aqui usamos apenas o ciclo das cinco naturezas. Não aplicamos as regras de vitória das combinações daquele jogo.</p><p>Referência narrativa das transformações: Naruto, capítulos 315–316. <a href="https://naruto.fandom.com/wiki/Nature_Transformation" target="_blank" rel="noopener noreferrer">Índice de referências na Narutopedia ↗</a>.</p><h3>Escolha o lance</h3><p>Os botões sob cada personagem escolhem a natureza usada no lance. A roda pode acompanhar A ou B; clicar em outro elemento abre uma consulta livre e não concede uma nova habilidade ao ninja. A matriz ativa somente naturezas registradas para os dois personagens.</p><h3>Trajetória e cobertura</h3><p>O catálogo agrega toda a trajetória e diferentes mídias, sem recorte de fase. Habilidades emprestadas ou temporárias podem estar presentes. A indicação “a” preserva um rótulo de anime encontrado na origem; não é um filtro de cânone. Ausência de registro não comprova incapacidade.</p><h3>Além dos cinco elementos</h3><p>Kekkei genkai, naturezas combinadas, Yin e Yang não recebem multiplicadores. Condições específicas, como a argila explosiva de Deidara diante do Relâmpago, aparecem com referência própria. “Sem relação direta” significa que o ciclo não estabelece superioridade para aquele par.</p><h3>Leitura tática</h3><p>Há ${duelEditorial.profiles.length} perfis editoriais de recursos e condições, com fontes oficiais em cada ficha. Para outros personagens, mostramos os vínculos disponíveis e sinalizamos a ausência de curadoria específica. Quantidade de técnicas, naturezas e votos não é nota de poder.</p>`);
  }
  root.addEventListener('click',event=>{
    const nature=event.target.closest('[data-duel-nature]');if(nature){const side=nature.dataset.side;if(!duelNatureRows(state[side]).some(e=>e.key===nature.dataset.duelNature))return;state[side==='a'?'duelA':'duelB']=nature.dataset.duelNature;state.duelFocusSide=side;state.duelFocus=nature.dataset.duelNature;renderDuel();return}
    const focus=event.target.closest('[data-duel-focus]');if(focus){state.duelFocus=focus.dataset.duelFocus;state.duelFocusSide=null;renderDuelWheel();return}
    const pair=event.target.closest('[data-duel-pair-a]');if(pair&&!pair.disabled){state.duelA=pair.dataset.duelPairA;state.duelB=pair.dataset.duelPairB;state.duelFocusSide='a';renderDuel();return}
    const tab=event.target.closest('[data-duel-tab]');if(tab){state.duelTab=tab.dataset.duelTab;renderDuelTab();return}
    const button=event.target.closest('[data-duel-action]');if(!button||button.disabled)return;
    const action=button.dataset.duelAction;
    if(action==='swap'){[state.a,state.b]=[state.b,state.a];[state.duelA,state.duelB]=[state.duelB,state.duelA];state.duelQuery='';state.duelFocusSide='a';renderDuel()}
    else if(action==='focus'){state.duelFocusSide=button.dataset.side;state.duelFocus=state[button.dataset.side==='a'?'duelA':'duelB'];renderDuelWheel()}
